public static class Solution
{
    public static string FormatReceiptLine(string item, decimal price)
    {
        string name = item.Length <= 12 ? item : item.Substring(0, 12);
        string priceText = price.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture);
        return name.PadRight(12) + " " + priceText.PadLeft(8);
    }
}

