public static class Solution
{
    public static string BuildReceipt(IEnumerable<(string Name, int Quantity, decimal UnitPrice)> items)
    {
        var sb = new System.Text.StringBuilder();
        decimal total = 0m;
        bool first = true;
        foreach (var item in items)
        {
            if (!first)
            {
                sb.Append('\n');
            }
            first = false;
            decimal lineTotal = item.Quantity * item.UnitPrice;
            total += lineTotal;
            sb.Append(item.Quantity);
            sb.Append(" x ");
            sb.Append(item.Name);
            sb.Append(" @ ");
            sb.Append(item.UnitPrice.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture));
            sb.Append(" = ");
            sb.Append(lineTotal.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture));
        }
        if (!first)
        {
            sb.Append('\n');
        }
        sb.Append("Total: ");
        sb.Append(total.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture));
        return sb.ToString();
    }
}

