public static class Solution
{
    public static string FormatTableRow(string[] cells, int[] widths)
    {
        if (cells.Length != widths.Length)
        {
            throw new ArgumentException("Cells and widths must have the same length.");
        }
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < cells.Length; i++)
        {
            if (i > 0)
            {
                sb.Append(" | ");
            }
            string cell = cells[i].Length <= widths[i] ? cells[i] : cells[i].Substring(0, widths[i]);
            sb.Append(cell.PadRight(widths[i]));
        }
        return sb.ToString();
    }
}

