public static class Solution
{
    public static string FormatColumns(IEnumerable<string> left, IEnumerable<string> right, int leftWidth)
    {
        var sb = new System.Text.StringBuilder();
        using var leftEnum = left.GetEnumerator();
        using var rightEnum = right.GetEnumerator();
        bool first = true;
        while (leftEnum.MoveNext() && rightEnum.MoveNext())
        {
            if (!first) sb.Append(Environment.NewLine);
            first = false;
            sb.Append(leftEnum.Current.PadRight(leftWidth));
            sb.Append(' ');
            sb.Append(rightEnum.Current);
        }
        return sb.ToString();
    }
}

