public record ReceiptItem(string Name, decimal Price, int Quantity);

public static class Solution
{
    public static string FormatReceipt(IEnumerable<ReceiptItem> items)
    {
        var sb = new System.Text.StringBuilder();
        decimal grandTotal = 0m;
        bool first = true;
        foreach (var item in items)
        {
            decimal total = item.Price * item.Quantity;
            grandTotal += total;
            if (!first) sb.Append(Environment.NewLine);
            first = false;
            sb.Append($"{item.Name,-20} {item.Quantity,3} x {item.Price,8:F2} = {total,8:F2}");
        }
        if (!first) sb.Append(Environment.NewLine);
        sb.Append($"Total: {grandTotal,8:F2}");
        return sb.ToString();
    }
}

