    public static string RepeatWithSeparator(string value, int count, string separator)
    {
        if (count <= 0) return string.Empty;
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < count; i++)
        {
            if (i > 0) sb.Append(separator);
            sb.Append(value);
        }
        return sb.ToString();
    }
}

