public static class Solution
{
    public static double AverageScore(IReadOnlyList<int> scores)
    {
        if (scores.Count == 0)
        {
            return 0.0;
        }

        int sum = 0;
        foreach (int score in scores)
        {
            sum += score;
        }

        return (double)sum / scores.Count;
    }
}

