public static class Solution
{
    public static IReadOnlyDictionary<char, int> GradeDistribution(IReadOnlyList<double> scores)
    {
        var distribution = new Dictionary<char, int>
        {
            ['A'] = 0,
            ['B'] = 0,
            ['C'] = 0,
            ['D'] = 0,
            ['F'] = 0
        };

        foreach (double score in scores)
        {
            char grade;
            if (score >= 90.0)
            {
                grade = 'A';
            }
            else if (score >= 80.0)
            {
                grade = 'B';
            }
            else if (score >= 70.0)
            {
                grade = 'C';
            }
            else if (score >= 60.0)
            {
                grade = 'D';
            }
            else
            {
                grade = 'F';
            }

            distribution[grade]++;
        }

        return distribution;
    }
}

