public static class Solution
{
    public static IReadOnlyList<int> CurveScores(IReadOnlyList<int> scores, int curve)
    {
        var curved = new List<int>(scores.Count);
        foreach (int score in scores)
        {
            int newScore = score + curve;
            if (newScore > 100)
            {
                newScore = 100;
            }
            curved.Add(newScore);
        }
        return curved;
    }
}

