solution:
public static class Solution
{
    public static bool TryParseDuration(string? text, out int totalMinutes)
    {
        totalMinutes = 0;
        if (string.IsNullOrEmpty(text))
        {
            return false;
        }
        int colonIndex = text.IndexOf(':');
        if (colonIndex <= 0 || colonIndex != text.Length - 3)
        {
            return false;
        }
        string hoursPart = text.Substring(0, colonIndex);
        string minutesPart = text.Substring(colonIndex + 1);
        if (minutesPart.Length != 2 || !int.TryParse(hoursPart, out int hours) || !int.TryParse(minutesPart, out int minutes))
        {
            return false;
        }
        if (hours < 0 || minutes < 0 || minutes > 59)
        {
            return false;
        }
        totalMinutes = hours * 60 + minutes;
        return true;
    }
}

