        var parts = hhmm.Split(':');
        if (parts.Length != 2) throw new FormatException();
        if (!int.TryParse(parts[0], out int hours)) throw new FormatException();
        if (parts[1].Length != 2 || !int.TryParse(parts[1], out int minutes)) throw new FormatException();
        if (minutes < 0 || minutes >= 60) throw new FormatException();
        return hours * 60 + minutes;
    }
}

