public static class Solution
{
    public static int ParseDuration(string text)
    {
        if (string.IsNullOrEmpty(text)) throw new FormatException("Duration is empty.");
        int colon = text.IndexOf(':');
        if (colon <= 0 || colon == text.Length - 1) throw new FormatException("Duration must be in hh:mm format.");
        string hoursText = text[..colon];
        string minutesText = text[(colon + 1)..];
        if (minutesText.Length != 2) throw new FormatException("Minutes must be two digits.");
        if (!int.TryParse(hoursText, out int hours)) throw new FormatException("Hours must be an integer.");
        if (!int.TryParse(minutesText, out int minutes) || minutes < 0 || minutes > 59) throw new FormatException("Minutes must be between 00 and 59.");
        if (hours < 0) throw new FormatException("Hours must be non-negative.");
        return hours * 60 + minutes;
    }
}

