public static class Solution
{
    public static List<int> ProcessQueueOperations(string[] operations)
    {
        Stack<int> input = new Stack<int>();
        Stack<int> output = new Stack<int>();
        List<int> results = new List<int>();
        foreach (string op in operations)
        {
            if (op.StartsWith("enqueue "))
            {
                int val = int.Parse(op.Substring(8));
                input.Push(val);
            }
            else if (op == "dequeue")
            {
                if (output.Count == 0)
                {
                    while (input.Count > 0)
                    {
                        output.Push(input.Pop());
                    }
                }
                if (output.Count > 0)
                {
                    results.Add(output.Pop());
                }
            }
        }
        return results;
    }
}

