public static class Solution
{
    public static int FirstUnmatchedIndex(string s)
    {
        Stack<(char, int)> stack = new Stack<(char, int)>();
        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            if (c == '(' || c == '{' || c == '[')
            {
                stack.Push((c, i));
            }
            else if (c == ')' || c == '}' || c == ']')
            {
                if (stack.Count == 0) return i;
                var (open, _) = stack.Pop();
                if ((c == ')' && open != '(') ||
                    (c == '}' && open != '{') ||
                    (c == ']' && open != '['))
                {
                    return i;
                }
            }
        }
        return -1;
    }
}

