public static class Solution
{
    public static int ProcessOrders(Queue<int> orders, int count)
    {
        if (count < 0)
        {
            count = 0;
        }

        int processed = 0;
        while (processed < count && orders.Count > 0)
        {
            orders.Dequeue();
            processed++;
        }

        return processed;
    }
}

