public record Order(int Id, string Customer);

public static class Solution
{
    public static int ProcessUntilCustomer(Queue<Order> orders, string customer)
    {
        int processed = 0;
        while (orders.Count > 0)
        {
            Order order = orders.Dequeue();
            processed++;
            if (order.Customer == customer)
            {
                break;
            }
        }

        return processed;
    }
}

