public static class Solution
{
    public static string UndoEdits(string initial, IReadOnlyList<string> edits, int undoCount)
    {
        if (undoCount < 0)
        {
            undoCount = 0;
        }

        Stack<string> history = new Stack<string>();
        string current = initial;

        foreach (string edit in edits)
        {
            history.Push(current);
            current += edit;
        }

        int undos = Math.Min(undoCount, history.Count);
        for (int i = 0; i < undos; i++)
        {
            current = history.Pop();
        }

        return current;
    }
}

