public static class Solution
{
    public static List<int> ProcessCommands(IReadOnlyList<string> commands)
    {
        Stack<int> undo = new Stack<int>();
        Stack<int> redo = new Stack<int>();

        foreach (string command in commands)
        {
            if (command.StartsWith("add ", StringComparison.Ordinal))
            {
                int value = int.Parse(command.Substring(4));
                undo.Push(value);
                redo.Clear();
            }
            else if (command == "undo")
            {
                if (undo.Count > 0)
                {
                    redo.Push(undo.Pop());
                }
            }
            else if (command == "redo")
            {
                if (redo.Count > 0)
                {
                    undo.Push(redo.Pop());
                }
            }
        }

        return undo.Reverse().ToList();
    }
}

