    public static List<string> ProcessOrderLog(IReadOnlyList<string> actions)
    {
        Queue<string> orders = new Queue<string>();
        List<string> processed = new List<string>();

        foreach (string action in actions)
        {
            if (action.StartsWith("enqueue ", StringComparison.Ordinal))
            {
                string name = action.Substring(8);
                orders.Enqueue(name);
            }
            else if (action == "process")
            {
                if (orders.Count > 0)
                {
                    processed.Add(orders.Dequeue());
                }
                else
                {
                    processed.Add("(none)");
                }
            }
        }

        return processed;
    }
}

