public static class Solution
{
    public static int ProcessOrders(Queue<int> orders, int capacity)
    {
        int processed = 0;
        while (orders.Count > 0 && capacity >= orders.Peek())
        {
            capacity -= orders.Dequeue();
            processed++;
        }
        return processed;
    }
}

