public static class Solution
{
    public static void ReverseQueue(Queue<int> queue)
    {
        var stack = new Stack<int>();
        while (queue.Count > 0)
        {
            stack.Push(queue.Dequeue());
        }
        while (stack.Count > 0)
        {
            queue.Enqueue(stack.Pop());
        }
    }
}

