public static class Solution
{
    public static int FirstMismatchIndex(string s)
    {
        var stack = new Stack<int>();
        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push(i);
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                if (stack.Count == 0)
                {
                    return i;
                }
                char open = s[stack.Pop()];
                if ((c == ')' && open != '(') || (c == ']' && open != '[') || (c == '}' && open != '{'))
                {
                    return i;
                }
            }
        }
        if (stack.Count == 0)
        {
            return -1;
        }
        int[] indices = stack.ToArray();
        return indices[^1];
    }
}

