public static class Solution
{
    public static int ProcessOrdersWithPriority(Queue<int> normal, Stack<int> priority, int capacity)
    {
        int processed = 0;
        while (priority.Count > 0 && priority.Peek() <= capacity)
        {
            capacity -= priority.Pop();
            processed++;
        }
        while (normal.Count > 0 && normal.Peek() <= capacity)
        {
            capacity -= normal.Dequeue();
            processed++;
        }
        return processed;
    }
}

