public static class Solution
{
    public static List<int> ProcessOrders(Queue<int> orders, int capacity)
    {
        var result = new List<int>();
        int remaining = capacity;
        foreach (int order in orders)
        {
            if (order <= remaining)
            {
                result.Add(order);
                remaining -= order;
            }
            else
            {
                break;
            }
        }
        return result;
    }
}

