public static class Solution
{
    public static Queue<int> ReverseFirstK(Queue<int> queue, int k)
    {
        var copy = new Queue<int>(queue);
        var result = new Queue<int>();
        if (k <= 0 || k > copy.Count)
        {
            return copy;
        }
        var stack = new Stack<int>();
        for (int i = 0; i < k; i++)
        {
            stack.Push(copy.Dequeue());
        }
        while (stack.Count > 0)
        {
            result.Enqueue(stack.Pop());
        }
        while (copy.Count > 0)
        {
            result.Enqueue(copy.Dequeue());
        }
        return result;
    }
}

