public static class Solution
{
    public static string MinRemoveToMakeValid(string s)
    {
        var chars = s.ToCharArray();
        var stack = new Stack<int>();
        for (int i = 0; i < chars.Length; i++)
        {
            if (chars[i] == '(')
            {
                stack.Push(i);
            }
            else if (chars[i] == ')')
            {
                if (stack.Count > 0)
                {
                    stack.Pop();
                }
                else
                {
                    chars[i] = '\0';
                }
            }
        }
        while (stack.Count > 0)
        {
            chars[stack.Pop()] = '\0';
        }
        int write = 0;
        for (int i = 0; i < chars.Length; i++)
        {
            if (chars[i] != '\0')
            {
                chars[write++] = chars[i];
            }
        }
        return new string(chars, 0, write);
    }
}

