public static class Solution
{
    public static bool AreBracketsBalanced(string input)
    {
        Stack<char> stack = new Stack<char>();
        foreach (char c in input)
        {
            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push(c);
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                if (stack.Count == 0)
                {
                    return false;
                }
                char open = stack.Pop();
                if (c == ')' && open != '(')
                {
                    return false;
                }
                if (c == ']' && open != '[')
                {
                    return false;
                }
                if (c == '}' && open != '{')
                {
                    return false;
                }
            }
        }
        return stack.Count == 0;
    }
}

