    public static List<string> ProcessUndoRedoCommands(IEnumerable<string> commands)
    {
        Stack<string> undo = new Stack<string>();
        Stack<string> redo = new Stack<string>();
        foreach (string command in commands)
        {
            if (command.StartsWith("DO:", StringComparison.Ordinal))
            {
                string action = command.Substring(3);
                undo.Push(action);
                redo.Clear();
            }
            else if (command == "UNDO")
            {
                if (undo.Count > 0)
                {
                    redo.Push(undo.Pop());
                }
            }
            else if (command == "REDO")
            {
                if (redo.Count > 0)
                {
                    undo.Push(redo.Pop());
                }
            }
        }
        return undo.ToList();
    }
}

