public static class Solution
{
    public static string UndoLastEdits(string text, int undoCount)
    {
        if (undoCount <= 0 || text.Length == 0)
        {
            return text;
        }

        var stack = new Stack<char>();
        foreach (char c in text)
        {
            stack.Push(c);
        }

        while (undoCount > 0 && stack.Count > 0)
        {
            stack.Pop();
            undoCount--;
        }

        var chars = new char[stack.Count];
        for (int i = chars.Length - 1; i >= 0; i--)
        {
            chars[i] = stack.Pop();
        }

        return new string(chars);
    }
}

