public static class Solution
{
    public static int RunWithUndo(IEnumerable<string> commands)
    {
        int value = 0;
        var history = new Stack<int>();
        foreach (string command in commands)
        {
            if (command == "undo")
            {
                if (history.Count > 0)
                {
                    value -= history.Pop();
                }
            }
            else if (command.StartsWith("add ", StringComparison.Ordinal))
            {
                int amount = int.Parse(command.Substring(4));
                value += amount;
                history.Push(amount);
            }
            else if (command.StartsWith("sub ", StringComparison.Ordinal))
            {
                int amount = int.Parse(command.Substring(4));
                value -= amount;
                history.Push(-amount);
            }
        }
        return value;
    }
}

