public static class Solution
{
    public static void UndoLastProcessed(Queue<int> pending, Stack<int> processed)
    {
        if (processed.Count == 0)
        {
            return;
        }

        int undone = processed.Pop();
        var temp = new Queue<int>();
        temp.Enqueue(undone);
        while (pending.Count > 0)
        {
            temp.Enqueue(pending.Dequeue());
        }
        while (temp.Count > 0)
        {
            pending.Enqueue(temp.Dequeue());
        }
    }
}

