public record Point(double X, double Y);
public record Segment(Point Start, Point End);
public static class Solution
{
    public static double DistanceToSegment(Point point, Segment segment)
    {
        double vx = segment.End.X - segment.Start.X;
        double vy = segment.End.Y - segment.Start.Y;
        double wx = point.X - segment.Start.X;
        double wy = point.Y - segment.Start.Y;

        double c1 = vx * wx + vy * wy;
        if (c1 <= 0.0)
        {
            return Distance(point, segment.Start);
        }

        double c2 = vx * vx + vy * vy;
        if (c2 <= c1)
        {
            return Distance(point, segment.End);
        }

        double t = c1 / c2;
        double projX = segment.Start.X + t * vx;
        double projY = segment.Start.Y + t * vy;
        return Distance(point, new Point(projX, projY));
    }

    private static double Distance(Point a, Point b)
    {
        double dx = a.X - b.X;
        double dy = a.Y - b.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }
}

