public abstract record Shape;
public sealed record Rectangle(double Width, double Height) : Shape;
public sealed record Circle(double Radius) : Shape;
public sealed record Triangle(double A, double B, double C) : Shape;

public static class Solution
{
    public static double TotalArea(List<Shape> shapes) => shapes.Sum(Area);

    public static double TotalPerimeter(List<Shape> shapes) => shapes.Sum(Perimeter);

    private static double Area(Shape shape) => shape switch
    {
        Rectangle r => r.Width * r.Height,
        Circle c => Math.PI * c.Radius * c.Radius,
        Triangle t => TriangleArea(t.A, t.B, t.C),
        _ => throw new ArgumentException("Unknown shape", nameof(shape))
    };

    private static double Perimeter(Shape shape) => shape switch
    {
        Rectangle r => 2 * (r.Width + r.Height),
        Circle c => 2 * Math.PI * c.Radius,
        Triangle t => t.A + t.B + t.C,
        _ => throw new ArgumentException("Unknown shape", nameof(shape))
    };

    private static double TriangleArea(double a, double b, double c)
    {
        double s = (a + b + c) / 2;
        return Math.Sqrt(s * (s - a) * (s - b) * (s - c));
    }
}

