public record Point(double X, double Y);
public record Triangle(Point A, Point B, Point C)
{
    public double Perimeter()
    {
        return Distance(A, B) + Distance(B, C) + Distance(C, A);
    }

    public double Area()
    {
        return Math.Abs((A.X * (B.Y - C.Y) + B.X * (C.Y - A.Y) + C.X * (A.Y - B.Y)) / 2.0);
    }

    private static double Distance(Point a, Point b)
    {
        double dx = a.X - b.X;
        double dy = a.Y - b.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }
}

public static class Solution
{
    public static bool IsRight(Triangle triangle)
    {
        double a = Distance(triangle.B, triangle.C);
        double b = Distance(triangle.A, triangle.C);
        double c = Distance(triangle.A, triangle.B);
        double[] sides = new[] { a, b, c };
        Array.Sort(sides);
        return Math.Abs(sides[2] * sides[2] - (sides[0] * sides[0] + sides[1] * sides[1])) < 1e-9;
    }

    private static double Distance(Point a, Point b)
    {
        double dx = a.X - b.X;
        double dy = a.Y - b.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }
}

