public record Point(double X, double Y);
public record Rectangle(Point TopLeft, double Width, double Height)
{
    public double Area() => Width * Height;
    public double Perimeter() => 2 * (Width + Height);
}

public static class Solution
{
    public static double DistanceTo(Rectangle rectangle, Point point)
    {
        double left = rectangle.TopLeft.X;
        double top = rectangle.TopLeft.Y;
        double right = left + rectangle.Width;
        double bottom = top + rectangle.Height;

        double dx = 0;
        if (point.X < left)
        {
            dx = left - point.X;
        }
        else if (point.X > right)
        {
            dx = point.X - right;
        }

        double dy = 0;
        if (point.Y < top)
        {
            dy = top - point.Y;
        }
        else if (point.Y > bottom)
        {
            dy = point.Y - bottom;
        }

        return Math.Sqrt(dx * dx + dy * dy);
    }
}

