public record Point(double X, double Y);
public record Polygon(Point[] Vertices);

public static class Solution
{
    public static double PolygonPerimeter(Polygon p)
    {
        if (p.Vertices.Length < 2) return 0;
        double total = 0;
        for (int i = 0; i < p.Vertices.Length; i++)
        {
            Point a = p.Vertices[i];
            Point b = p.Vertices[(i + 1) % p.Vertices.Length];
            double dx = b.X - a.X;
            double dy = b.Y - a.Y;
            total += Math.Sqrt(dx * dx + dy * dy);
        }
        return total;
    }

    public static double PolygonArea(Polygon p)
    {
        if (p.Vertices.Length < 3) return 0;
        double sum = 0;
        for (int i = 0; i < p.Vertices.Length; i++)
        {
            Point a = p.Vertices[i];
            Point b = p.Vertices[(i + 1) % p.Vertices.Length];
            sum += a.X * b.Y - b.X * a.Y;
        }
        return Math.Abs(sum) / 2.0;
    }
}

