public record Point(double X, double Y);
public record BoundingBox(Point Min, Point Max);

public static class Solution
{
    public static bool Contains(BoundingBox box, Point p)
    {
        return p.X >= box.Min.X && p.X <= box.Max.X &&
               p.Y >= box.Min.Y && p.Y <= box.Max.Y;
    }

    public static double DistanceTo(BoundingBox box, Point p)
    {
        double dx = 0;
        if (p.X < box.Min.X) dx = box.Min.X - p.X;
        else if (p.X > box.Max.X) dx = p.X - box.Max.X;

        double dy = 0;
        if (p.Y < box.Min.Y) dy = box.Min.Y - p.Y;
        else if (p.Y > box.Max.Y) dy = p.Y - box.Max.Y;

        return Math.Sqrt(dx * dx + dy * dy);
    }
}

