public record Point(double X, double Y);
public record Triangle(Point A, Point B, Point C);

public static class Solution
{
    public static double Perimeter(Triangle t)
    {
        return Distance(t.A, t.B) + Distance(t.B, t.C) + Distance(t.C, t.A);
    }

    public static double Area(Triangle t)
    {
        double a = Distance(t.B, t.C);
        double b = Distance(t.A, t.C);
        double c = Distance(t.A, t.B);
        double s = (a + b + c) / 2;
        return Math.Sqrt(Math.Max(0, s * (s - a) * (s - b) * (s - c)));
    }

    private static double Distance(Point p, Point q)
    {
        double dx = p.X - q.X;
        double dy = p.Y - q.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }
}

