public record Point(double X, double Y);
public record Segment(Point Start, Point End);

public static class Solution
{
    public static double DistanceToSegment(Point p, Segment s)
    {
        double dx = s.End.X - s.Start.X;
        double dy = s.End.Y - s.Start.Y;
        double lengthSquared = dx * dx + dy * dy;
        if (lengthSquared == 0)
        {
            return Distance(p, s.Start);
        }
        double t = ((p.X - s.Start.X) * dx + (p.Y - s.Start.Y) * dy) / lengthSquared;
        t = Math.Max(0, Math.Min(1, t));
        double projX = s.Start.X + t * dx;
        double projY = s.Start.Y + t * dy;
        double ddx = p.X - projX;
        double ddy = p.Y - projY;
        return Math.Sqrt(ddx * ddx + ddy * ddy);
    }

    private static double Distance(Point a, Point b)
    {
        double dx = a.X - b.X;
        double dy = a.Y - b.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }
}

