public record BankAccount(decimal Balance);

public static class Solution
{
    public static BankAccount ApplyTransactions(BankAccount account, IEnumerable<decimal> transactions)
    {
        if (transactions is null) throw new ArgumentNullException(nameof(transactions));
        var balance = account.Balance;
        foreach (var amount in transactions)
        {
            if (amount == 0) continue;
            if (amount > 0) balance += amount;
            else
            {
                var withdrawal = -amount;
                if (withdrawal > balance) throw new InvalidOperationException("Insufficient funds.");
                balance -= withdrawal;
            }
        }
        return account with { Balance = balance };
    }
}

