{
    public static BankAccount ApplyTransactions(BankAccount account, IEnumerable<decimal> transactions)
    {
        if (transactions is null)
        {
            throw new ArgumentNullException(nameof(transactions));
        }

        var balance = account.Balance;
        foreach (var amount in transactions)
        {
            if (amount == 0m)
            {
                throw new ArgumentOutOfRangeException(nameof(transactions), "Transaction amount must not be zero.");
            }

            if (amount > 0m)
            {
                balance += amount;
            }
            else
            {
                var withdrawal = -amount;
                if (withdrawal > balance)
                {
                    throw new InvalidOperationException("Insufficient funds.");
                }
                balance -= withdrawal;
            }
        }

        return account with { Balance = balance };
    }
}

