public record Transaction(string Kind, decimal Amount);

public static class Solution
{
    public static decimal ProcessTransactions(decimal initialBalance, IReadOnlyList<Transaction> transactions)
    {
        decimal balance = initialBalance;
        foreach (var txn in transactions)
        {
            if (txn.Amount <= 0m) throw new ArgumentOutOfRangeException(nameof(txn));
            if (txn.Kind.Equals("deposit", StringComparison.OrdinalIgnoreCase))
            {
                balance += txn.Amount;
            }
            else if (txn.Kind.Equals("withdraw", StringComparison.OrdinalIgnoreCase))
            {
                if (txn.Amount > balance) throw new InvalidOperationException("Insufficient funds");
                balance -= txn.Amount;
            }
            else
            {
                throw new ArgumentException("Unknown transaction kind", nameof(txn));
            }
        }
        return balance;
    }
}

