public record BankAccount(decimal Balance);

public static class Solution
{
    public static BankAccount ProcessTransactions(BankAccount account, IEnumerable<decimal> transactions)
    {
        var balance = account.Balance;
        foreach (var transaction in transactions)
        {
            if (transaction == 0m)
            {
                throw new ArgumentOutOfRangeException(nameof(transactions));
            }
            if (transaction > 0m)
            {
                balance += transaction;
            }
            else
            {
                var withdrawal = -transaction;
                if (withdrawal > balance)
                {
                    throw new InvalidOperationException("Insufficient funds");
                }
                balance -= withdrawal;
            }
        }
        return new BankAccount(balance);
    }
}

