{
    public static int CountOccurrences(int[] sorted, int target)
    {
        int first = LowerBound(sorted, target);
        if (first == sorted.Length || sorted[first] != target) return 0;
        int last = UpperBound(sorted, target);
        return last - first;
    }

    private static int LowerBound(int[] sorted, int target)
    {
        int low = 0;
        int high = sorted.Length;
        while (low < high)
        {
            int mid = low + (high - low) / 2;
            if (sorted[mid] < target) low = mid + 1;
            else high = mid;
        }
        return low;
    }

    private static int UpperBound(int[] sorted, int target)
    {
        int low = 0;
        int high = sorted.Length;
        while (low < high)
        {
            int mid = low + (high - low) / 2;
            if (sorted[mid] <= target) low = mid + 1;
            else high = mid;
        }
        return low;
    }
}

