public static class Solution
{
    public static int ClosestIndex(int[]? sorted, int target)
    {
        if (sorted is null || sorted.Length == 0) return -1;
        int low = 0;
        int high = sorted.Length - 1;
        while (low < high)
        {
            int mid = low + (high - low) / 2;
            if (sorted[mid] < target) low = mid + 1;
            else high = mid;
        }
        int candidate = low;
        if (candidate > 0 && Math.Abs((long)sorted[candidate] - target) >= Math.Abs((long)sorted[candidate - 1] - target))
        {
            candidate = candidate - 1;
        }
        return candidate;
    }
}

