public static class Solution
{
    public static int SearchRotated(int[] rotatedSortedValues, int target)
    {
        int left = 0;
        int right = rotatedSortedValues.Length - 1;
        while (left <= right)
        {
            int mid = left + (right - left) / 2;
            if (rotatedSortedValues[mid] == target)
            {
                return mid;
            }
            if (rotatedSortedValues[left] <= rotatedSortedValues[mid])
            {
                if (rotatedSortedValues[left] <= target && target < rotatedSortedValues[mid])
                {
                    right = mid - 1;
                }
                else
                {
                    left = mid + 1;
                }
            }
            else
            {
                if (rotatedSortedValues[mid] < target && target <= rotatedSortedValues[right])
                {
                    left = mid + 1;
                }
                else
                {
                    right = mid - 1;
                }
            }
        }
        return -1;
    }
}

