public static class Solution
{
    public static int FindStringIndex(string text, string value)
    {
        if (value.Length == 0)
        {
            return 0;
        }

        if (value.Length > text.Length)
        {
            return -1;
        }

        for (int i = 0; i <= text.Length - value.Length; i++)
        {
            int j = 0;
            while (j < value.Length && text[i + j] == value[j])
            {
                j++;
            }

            if (j == value.Length)
            {
                return i;
            }
        }

        return -1;
    }
}

