        int lastDot = emailDomain.LastIndexOf('.');
        if (lastDot <= 0 || lastDot == emailDomain.Length - 1) return false;
        return string.Equals(emailDomain, domain, StringComparison.OrdinalIgnoreCase);
    }
}

