        if (maxLocalPartLength <= 0 || maxDomainLength <= 0) return false;
        if (email.Any(char.IsWhiteSpace)) return false;
        int atIndex = email.IndexOf('@');
        if (atIndex <= 0) return false;
        if (email.IndexOf('@', atIndex + 1) != -1) return false;
        string local = email[..atIndex];
        string domain = email[(atIndex + 1)..];
        if (local.Length > maxLocalPartLength) return false;
        if (domain.Length > maxDomainLength) return false;
        if (domain.Length == 0) return false;
        int lastDot = domain.LastIndexOf('.');
        if (lastDot <= 0 || lastDot == domain.Length - 1) return false;
        return true;
    }
}

