public sealed record PasswordPolicy(int MinLength, bool RequireDigit, bool RequireUppercase, bool RequireLowercase, bool RequireSpecial);

public static class Solution
{
    public static bool MeetsPasswordPolicy(string? password, PasswordPolicy policy)
    {
        if (password is null || password.Length < policy.MinLength)
        {
            return false;
        }

        bool hasDigit = false;
        bool hasUpper = false;
        bool hasLower = false;
        bool hasSpecial = false;

        foreach (char c in password)
        {
            if (char.IsDigit(c)) hasDigit = true;
            else if (char.IsUpper(c)) hasUpper = true;
            else if (char.IsLower(c)) hasLower = true;
            else hasSpecial = true;
        }

        return (!policy.RequireDigit || hasDigit)
            && (!policy.RequireUppercase || hasUpper)
            && (!policy.RequireLowercase || hasLower)
            && (!policy.RequireSpecial || hasSpecial);
    }
}

