        {
            return false;
        }

        foreach (char c in input)
        {
            if (c < '0' || c > '9')
            {
                return false;
            }
        }

        if (code is null || code.IsUsed || now > code.ExpiresAt)
        {
            return false;
        }

        return string.Equals(input, code.Code, StringComparison.Ordinal);
    }
}

