public record EmailValidationResult(bool IsValid, string? Error);

public static class Solution
{
    public static EmailValidationResult ValidateEmail(string email, string[] allowedDomains)
    {
        if (string.IsNullOrEmpty(email))
            return new EmailValidationResult(false, "Email is empty");
        if (email.Contains(' '))
            return new EmailValidationResult(false, "Email contains spaces");
        int atIndex = email.IndexOf('@');
        if (atIndex <= 0)
            return new EmailValidationResult(false, "Invalid local part or missing @");
        if (email.IndexOf('@', atIndex + 1) != -1)
            return new EmailValidationResult(false, "Multiple @ symbols");
        string domain = email.Substring(atIndex + 1);
        if (domain.Length == 0)
            return new EmailValidationResult(false, "Domain is empty");
        if (!domain.Contains('.'))
            return new EmailValidationResult(false, "Domain must contain a dot");
        if (domain.StartsWith('.') || domain.EndsWith('.'))
            return new EmailValidationResult(false, "Domain cannot start or end with a dot");
        foreach (string allowed in allowedDomains)
        {
            if (string.Equals(domain, allowed, StringComparison.OrdinalIgnoreCase))
                return new EmailValidationResult(true, null);
        }
        return new EmailValidationResult(false, "Domain not allowed");
    }
}

