public record PasswordPolicy(int MinLength, bool RequireUppercase, bool RequireLowercase, bool RequireDigit);

public static class Solution
{
    public static bool IsValidPassword(string password, PasswordPolicy policy)
    {
        if (string.IsNullOrEmpty(password)) return false;
        if (password.Length < policy.MinLength) return false;
        bool hasUpper = false, hasLower = false, hasDigit = false;
        foreach (char c in password)
        {
            if (char.IsUpper(c)) hasUpper = true;
            else if (char.IsLower(c)) hasLower = true;
            else if (char.IsDigit(c)) hasDigit = true;
        }
        if (policy.RequireUppercase && !hasUpper) return false;
        if (policy.RequireLowercase && !hasLower) return false;
        if (policy.RequireDigit && !hasDigit) return false;
        return true;
    }
}

