public static class Solution
{
    public static int MaxRowSumIndex(int[,] matrix)
    {
        int rows = matrix.GetLength(0);
        if (rows == 0)
        {
            return -1;
        }
        int cols = matrix.GetLength(1);
        int maxSum = int.MinValue;
        int maxIndex = 0;
        for (int i = 0; i < rows; i++)
        {
            int sum = 0;
            for (int j = 0; j < cols; j++)
            {
                sum += matrix[i, j];
            }
            if (sum > maxSum)
            {
                maxSum = sum;
                maxIndex = i;
            }
        }
        return maxIndex;
    }
}

