public static class Solution
{
    public static int PasswordScore(string? password)
    {
        if (password is null)
        {
            return 0;
        }

        int score = 0;
        if (password.Length >= 8)
        {
            score++;
        }

        bool hasLower = false;
        bool hasUpper = false;
        bool hasDigit = false;
        bool hasSpecial = false;

        foreach (char c in password)
        {
            if (char.IsLower(c))
            {
                hasLower = true;
            }
            else if (char.IsUpper(c))
            {
                hasUpper = true;
            }
            else if (char.IsDigit(c))
            {
                hasDigit = true;
            }
            else if (!char.IsLetterOrDigit(c))
            {
                hasSpecial = true;
            }
        }

        if (hasLower)
        {
            score++;
        }

        if (hasUpper)
        {
            score++;
        }

        if (hasDigit)
        {
            score++;
        }

        if (hasSpecial)
        {
            score++;
        }

        return score;
    }
}

