        List<List<int>> result = new List<List<int>>(cols);
        for (int j = 0; j < cols; j++)
        {
            List<int> newRow = new List<int>(rows);
            for (int i = 0; i < rows; i++)
            {
                newRow.Add(matrix[i][j]);
            }
            result.Add(newRow);
        }
        return result;
    }
}

