public static class Solution
{
    public static bool Contains(int[,] matrix, int value)
    {
        for (int r = 0; r < matrix.GetLength(0); r++)
        {
            for (int c = 0; c < matrix.GetLength(1); c++)
            {
                if (matrix[r, c] == value)
                {
                    return true;
                }
            }
        }
        return false;
    }

    public static int CountOccurrences(int[,] matrix, int value)
    {
        int count = 0;
        for (int r = 0; r < matrix.GetLength(0); r++)
        {
            for (int c = 0; c < matrix.GetLength(1); c++)
            {
                if (matrix[r, c] == value)
                {
                    count++;
                }
            }
        }
        return count;
    }
}

