    public static int GetOrDefault(List<List<int>> matrix, int row, int column, int defaultValue)
    {
        if (row < 0 || row >= matrix.Count)
        {
            return defaultValue;
        }
        List<int> targetRow = matrix[row];
        if (column < 0 || column >= targetRow.Count)
        {
            return defaultValue;
        }
        return targetRow[column];
    }
}

