    [KiteTest("transposes a 2D matrix")]
    public static void TestTranspose()
    {
        int[,] m = { { 1, 2, 3 }, { 4, 5, 6 } };
        int[,] expected = { { 1, 4 }, { 2, 5 }, { 3, 6 } };
        expect(MatrixEqual(Solution.Transpose(m), expected), "2x3 transpose");
        expect(MatrixEqual(Solution.Transpose(new int[0, 0]), new int[0, 0]), "empty matrix");
        expect(MatrixEqual(Solution.Transpose(new int[,] { { 7 } }), new int[,] { { 7 } }), "1x1 transpose");
