public static class Solution
{
    public static List<List<int>> TransposeJagged(List<List<int>> matrix)
    {
        int maxLen = 0;
        foreach (List<int> row in matrix)
        {
            if (row.Count > maxLen)
            {
                maxLen = row.Count;
            }
        }

        List<List<int>> result = new List<List<int>>();
        for (int c = 0; c < maxLen; c++)
        {
            List<int> newRow = new List<int>(matrix.Count);
            for (int r = 0; r < matrix.Count; r++)
            {
                if (c < matrix[r].Count)
                {
                    newRow.Add(matrix[r][c]);
                }
                else
                {
                    newRow.Add(0);
                }
            }
            result.Add(newRow);
        }
        return result;
    }
}

