public static class Solution
{
    public static string BuildCsvLine(IEnumerable<string> fields)
    {
        var sb = new System.Text.StringBuilder();
        bool first = true;
        foreach (var field in fields)
        {
            if (!first) sb.Append(',');
            first = false;
            bool needsQuote = field.Contains(',') || field.Contains('"') || field.Contains('\n');
            if (needsQuote)
            {
                sb.Append('"');
                sb.Append(field.Replace("\"", "\"\""));
                sb.Append('"');
            }
            else
            {
                sb.Append(field);
            }
        }
        return sb.ToString();
    }
}

