    {
        string priceText = price.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture);
        if (width <= 0) return string.Empty;
        if (width <= 10)
        {
            return priceText.Length > width ? priceText[..width] : priceText.PadLeft(width);
