        int itemWidth = width - 10;
        string itemPart = item.Length > itemWidth ? item[..itemWidth] : item.PadRight(itemWidth);
        string pricePart = priceText.Length > 10 ? priceText[..10] : priceText.PadLeft(10);
        return itemPart + pricePart;
    }
}

