public static class Solution
{
    public static string BuildCsvRow(params string?[] values)
    {
        System.Text.StringBuilder sb = new System.Text.StringBuilder();
        for (int i = 0; i < values.Length; i++)
        {
            if (i > 0) sb.Append(',');
            string? v = values[i];
            if (string.IsNullOrEmpty(v)) continue;
            bool mustQuote = v.IndexOfAny(new char[] { ',', (char)34, (char)10, (char)13 }) >= 0;
            if (mustQuote) sb.Append((char)34);
            foreach (char c in v)
            {
                if (c == (char)34)
                {
                    sb.Append((char)34);
                    sb.Append((char)34);
                }
                else sb.Append(c);
            }
            if (mustQuote) sb.Append((char)34);
        }
        return sb.ToString();
    }
}

