public record ReceiptItem(string Name, decimal Price);

public static class Solution
{
    public static string FormatReceipt(IEnumerable<ReceiptItem> items)
    {
        var lines = new List<string>();
        decimal total = 0m;
        foreach (var item in items)
        {
            total += item.Price;
            string name = item.Name.Length > 20 ? item.Name[..20] : item.Name.PadRight(20);
            string price = item.Price.ToString("F2", System.Globalization.CultureInfo.InvariantCulture).PadLeft(10);
            lines.Add(name + price);
        }
        string totalName = "TOTAL".PadRight(20);
        string totalText = total.ToString("F2", System.Globalization.CultureInfo.InvariantCulture).PadLeft(10);
        lines.Add(totalName + totalText);
        return string.Join("\n", lines);
    }
}

