public static class Solution
{
    public static string FormatTableRow(string[] cells, int[] widths, bool[] rightAlign)
    {
        System.Text.StringBuilder sb = new System.Text.StringBuilder();
        for (int i = 0; i < cells.Length; i++)
        {
            if (i > 0) sb.Append(" | ");
            int width = i < widths.Length ? widths[i] : cells[i].Length;
            string cell = cells[i].Length > width ? cells[i][..width] : cells[i];
            if (i < rightAlign.Length && rightAlign[i])
                sb.Append(cell.PadLeft(width));
            else
                sb.Append(cell.PadRight(width));
        }
        return sb.ToString();
    }
}

