public sealed record ReceiptItem(string Name, int Quantity, decimal UnitPrice);

public static class Solution
{
    public static string BuildReceipt(IEnumerable<ReceiptItem> items)
    {
        var sb = new System.Text.StringBuilder();
        decimal grandTotal = 0m;
        bool first = true;
        foreach (var item in items)
        {
            if (!first) sb.AppendLine();
            first = false;
            decimal lineTotal = item.Quantity * item.UnitPrice;
            grandTotal += lineTotal;
            string name = item.Name.PadRight(15);
            string qty = item.Quantity.ToString().PadLeft(3);
            string price = item.UnitPrice.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture).PadLeft(8);
            string total = lineTotal.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture).PadLeft(10);
            sb.Append(name).Append(' ').Append(qty).Append(' ').Append(price).Append(' ').Append(total);
        }
        if (!first)
        {
            sb.AppendLine();
            string totalLabel = "TOTAL".PadLeft(29);
            string totalValue = grandTotal.ToString("0.00", System.Globalization.CultureInfo.InvariantCulture).PadLeft(10);
            sb.Append(totalLabel).Append(' ').Append(totalValue);
        }
        return sb.ToString();
    }
}

