public static class Solution
{
    public static string BuildCsvLine(IReadOnlyList<string> values)
    {
        var sb = new System.Text.StringBuilder();
        for (int i = 0; i < values.Count; i++)
        {
            if (i > 0)
            {
                sb.Append(',');
            }
            string value = values[i];
            if (value.Contains(',') || value.Contains('"') || value.Contains((char)10) || value.Contains((char)13))
            {
                sb.Append('"').Append(value.Replace(new string('"', 1), new string('"', 2))).Append('"');
            }
            else
            {
                sb.Append(value);
            }
        }
        return sb.ToString();
    }
}

