public record StockItem(string Name, string Category, int Quantity, decimal UnitPrice);

public static class Solution
{
    public static List<StockItem> ApplyDiscount(IEnumerable<StockItem> items, string category, decimal percent)
    {
        if (percent < 0m || percent > 100m)
        {
            throw new ArgumentOutOfRangeException(nameof(percent));
        }

        return items.Select(item => item.Category == category
            ? item with { UnitPrice = item.UnitPrice * (100m - percent) / 100m }
            : item).ToList();
    }
}

