    public static Dictionary<string, decimal> ValueByCategory(IEnumerable<StockItem> items)
    {
        return items.GroupBy(item => item.Category)
                    .ToDictionary(group => group.Key, group => group.Sum(item => item.Quantity * item.UnitPrice));
