public record StockItem(string Sku, int Quantity, decimal UnitPrice);

public static class Solution
{
    public static List<StockItem> MergeInventory(IEnumerable<StockItem> first, IEnumerable<StockItem> second)
    {
        return first.Concat(second)
            .GroupBy(item => item.Sku)
            .Select(group =>
            {
                int totalQuantity = group.Sum(item => item.Quantity);
                decimal totalValue = group.Sum(item => item.Quantity * item.UnitPrice);
                decimal averagePrice = totalQuantity == 0 ? 0m : totalValue / totalQuantity;
                return new StockItem(group.Key, totalQuantity, averagePrice);
            })
            .ToList();
    }
}

