public static class Solution
{
    public static double MedianScore(IReadOnlyList<int> scores)
    {
        if (scores.Count == 0)
        {
            return 0;
        }
        var sorted = scores.OrderBy(s => s).ToList();
        int mid = sorted.Count / 2;
        if (sorted.Count % 2 == 1)
        {
            return sorted[mid];
        }
        return (sorted[mid - 1] + sorted[mid]) / 2.0;
    }
}

