    public static Dictionary<string, char> AssignGrades(Student[]? students)
    {
        var result = new Dictionary<string, char>();
        if (students == null) return result;
        foreach (var s in students)
        {
            double avg = 0.0;
            if (s.Scores != null && s.Scores.Length > 0)
                avg = s.Scores.Average();
            char grade;
            if (avg >= 90) grade = 'A';
            else if (avg >= 80) grade = 'B';
            else if (avg >= 70) grade = 'C';
            else if (avg >= 60) grade = 'D';
            else grade = 'F';
            result[s.Name] = grade;
        }
        return result;
    }
}

