public static class Solution
{
    public static string[] RankWithTies(Student[]? students)
    {
        if (students == null || students.Length == 0) return Array.Empty<string>();
        var ordered = students
            .Select(s => new { s.Name, Avg = s.Scores == null || s.Scores.Length == 0 ? 0.0 : s.Scores.Average() })
            .OrderByDescending(x => x.Avg)
            .ThenBy(x => x.Name)
            .ToArray();
        var result = new string[ordered.Length];
        int rank = 1;
        for (int i = 0; i < ordered.Length; i++)
        {
            if (i > 0 && ordered[i].Avg < ordered[i - 1].Avg)
                rank = i + 1;
            result[i] = ordered[i].Name + ": " + rank;
        }
        return result;
    }
}

