        if (student.Scores.Count == 0)
        {
            return 0.0;
        }

        return student.Scores.Average();
    }

    private static char GetLetterGrade(double average)
    {
        if (average >= 90.0) return 'A';
        if (average >= 80.0) return 'B';
        if (average >= 70.0) return 'C';
        if (average >= 60.0) return 'D';
        return 'F';
    }
}

