public static class Solution
{
    public static double WeightedAverage(IReadOnlyList<int> scores, IReadOnlyList<double> weights)
    {
        if (scores.Count != weights.Count || scores.Count == 0)
        {
            return 0;
        }

        double total = 0;
        double totalWeight = 0;
        for (int i = 0; i < scores.Count; i++)
        {
            total += scores[i] * weights[i];
            totalWeight += weights[i];
        }

        if (totalWeight <= 0)
        {
            return 0;
        }

        return total / totalWeight;
    }
}

