public record StudentScore(string Name, int Score);
public record RankedStudent(string Name, int Score, int Rank);
public static class Solution
{
    public static List<RankedStudent> DenseRank(IEnumerable<StudentScore> students)
    {
        var ordered = students
            .OrderByDescending(s => s.Score)
            .ThenBy(s => s.Name, StringComparer.Ordinal)
            .ToList();
        var result = new List<RankedStudent>();
        int rank = 0;
        int? previousScore = null;
        foreach (var student in ordered)
        {
            if (previousScore != student.Score)
            {
                rank++;
                previousScore = student.Score;
            }
            result.Add(new RankedStudent(student.Name, student.Score, rank));
        }
        return result;
    }
}

