        }

        if (!int.TryParse(parts[0], out int hours) || !int.TryParse(parts[1], out int minutes))
        {
            throw new FormatException("Invalid duration.");
        }

        if (hours < 0 || minutes < 0 || minutes > 59)
        {
            throw new FormatException("Invalid duration.");
        }

        return hours * 60 + minutes;
    }
}

