public static class Solution
{
    public static bool TryParseDuration(string? text, out int hours, out int minutes)
    {
        hours = 0;
        minutes = 0;
        if (text is null || text.Length == 0)
            return false;
        int colon = text.IndexOf(':');
        if (colon <= 0 || colon == text.Length - 1)
            return false;
        if (text.IndexOf(':', colon + 1) != -1)
            return false;
        string hourPart = text.Substring(0, colon);
        string minutePart = text.Substring(colon + 1);
        if (!int.TryParse(hourPart, out int h) || !int.TryParse(minutePart, out int m))
            return false;
        if (h < 0 || m < 0 || m > 59)
            return false;
        hours = h;
        minutes = m;
        return true;
    }
}

