public static class Solution
{
    public static int ParseHHMM(string text)
    {
        if (text is null) throw new ArgumentNullException(nameof(text));
        string[] parts = text.Split(':');
        if (parts.Length != 2) throw new FormatException("Expected hh:mm");
        string h = parts[0];
        string m = parts[1];
        if (h.Length < 2 || m.Length != 2) throw new FormatException("Invalid hh:mm");
        if (h.Any(c => !char.IsDigit(c)) || m.Any(c => !char.IsDigit(c))) throw new FormatException("Digits required");
        if (!int.TryParse(h, out int hours) || !int.TryParse(m, out int minutes)) throw new FormatException("Invalid number");
        if (minutes > 59) throw new FormatException("Minutes out of range");
        return hours * 60 + minutes;
    }
}

