public static class Solution
{
    public static int CountFulfilledOrders(Queue<int> orderAmounts, int dailyLimit)
    {
        int count = 0;
        int total = 0;
        while (orderAmounts.Count > 0)
        {
            int amount = orderAmounts.Peek();
            if (total + amount > dailyLimit)
            {
                break;
            }
            orderAmounts.Dequeue();
            total += amount;
            count++;
        }
        return count;
    }
}

