public static class Solution
{
    public static bool AreBracketsBalanced(string s)
    {
        Stack<char> stack = new Stack<char>();
        foreach (char c in s)
        {
            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push(c);
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                if (stack.Count == 0)
                {
                    return false;
                }
                char open = stack.Pop();
                if (!Matches(open, c))
                {
                    return false;
                }
            }
        }
        return stack.Count == 0;
    }

    private static bool Matches(char open, char close)
    {
        return (open == '(' && close == ')') ||
               (open == '[' && close == ']') ||
               (open == '{' && close == '}');
    }
}

