public static class Solution
{
    public static int FirstUnbalancedClosingIndex(string s)
    {
        Stack<char> stack = new Stack<char>();
        for (int i = 0; i < s.Length; i++)
        {
            char c = s[i];
            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push(c);
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                if (stack.Count == 0)
                {
                    return i;
                }
                char open = stack.Pop();
                if (!Matches(open, c))
                {
                    return i;
                }
            }
        }
        return -1;
    }

    private static bool Matches(char open, char close)
    {
        return (open == '(' && close == ')') ||
               (open == '[' && close == ']') ||
               (open == '{' && close == '}');
    }
}

