public static class Solution
{
    public static int MaxBracketDepth(string s)
    {
        Stack<char> stack = new Stack<char>();
        int max = 0;
        foreach (char c in s)
        {
            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push(c);
                if (stack.Count > max)
                {
                    max = stack.Count;
                }
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                if (stack.Count > 0)
                {
                    stack.Pop();
                }
            }
        }
        return max;
    }
}

