    public static List<string> ProcessOrdersWithCapacity(Queue<string> orders, int capacity)
    {
        var processed = new List<string>();
        if (capacity <= 0)
        {
            return processed;
        }
        int totalLength = 0;
        while (orders.Count > 0 && totalLength < capacity)
        {
            string order = orders.Dequeue();
            processed.Add(order);
            totalLength += order.Length;
        }
        return processed;
    }
}

