public static class Solution
{
    public static int? GetMin(Stack<int> stack)
    {
        if (stack.Count == 0)
        {
            return null;
        }
        int min = int.MaxValue;
        var temp = new Stack<int>();
        while (stack.Count > 0)
        {
            int val = stack.Pop();
            if (val < min) min = val;
            temp.Push(val);
        }
        while (temp.Count > 0)
        {
            stack.Push(temp.Pop());
        }
        return min;
    }
}

