    public static List<string> RoundRobin(Queue<string> orders, int cycles)
    {
        List<string> result = new List<string>();
        for (int i = 0; i < cycles; i++)
        {
            if (orders.Count == 0)
            {
                break;
            }
            string order = orders.Dequeue();
            result.Add(order);
            orders.Enqueue(order);
        }
        return result;
    }
}

