public static class Solution
{
    public static int MaxBracketDepth(string s)
    {
        var stack = new Stack<char>();
        int maxDepth = 0;
        foreach (char c in s)
        {
            if (c == '(' || c == '[' || c == '{')
            {
                stack.Push(c);
                if (stack.Count > maxDepth)
                {
                    maxDepth = stack.Count;
                }
            }
            else if (c == ')' || c == ']' || c == '}')
            {
                if (stack.Count == 0)
                {
                    return -1;
                }

                char open = stack.Pop();
                if (c == ')' && open != '(') return -1;
                if (c == ']' && open != '[') return -1;
                if (c == '}' && open != '{') return -1;
            }
        }

        return stack.Count == 0 ? maxDepth : -1;
    }
}

