public static class Solution
{
    public static List<string> UndoWithCapacity(IEnumerable<string> commands, int maxDepth)
    {
        var stack = new Stack<string>();
        foreach (var command in commands)
        {
            if (command == "UNDO")
            {
                if (stack.Count > 0)
                {
                    stack.Pop();
                }
            }
            else if (command.StartsWith("TYPE:", StringComparison.Ordinal))
            {
                if (maxDepth > 0)
                {
                    stack.Push(command.Substring(5));
                    while (stack.Count > maxDepth)
                    {
                        var temp = new Stack<string>();
                        while (stack.Count > 1)
                        {
                            temp.Push(stack.Pop());
                        }
                        stack.Pop();
                        while (temp.Count > 0)
                        {
                            stack.Push(temp.Pop());
                        }
                    }
                }
            }
        }

        var result = new List<string>(stack);
        result.Reverse();
        return result;
    }
}

