public static class Solution
{
    public static string ApplyUndoCommands(string initial, IReadOnlyList<string> commands)
    {
        var current = initial;
        var history = new Stack<string>();
        foreach (var command in commands)
        {
            if (command.Length > 0 && command[0] == '+')
            {
                var chunk = command.Substring(1);
                history.Push(chunk);
                current += chunk;
            }
            else if (command.Length == 1 && command[0] == '-')
            {
                if (history.Count > 0)
                {
                    var chunk = history.Pop();
                    current = current.Substring(0, current.Length - chunk.Length);
                }
            }
        }
        return current;
    }
}

