public static class Solution
{
    public static string ProcessEditsWithLimit(string initial, IReadOnlyList<string> commands, int maxUndoDepth)
    {
        var current = initial;
        var history = new Stack<string>();
        var depth = maxUndoDepth < 0 ? 0 : maxUndoDepth;
        foreach (var command in commands)
        {
            if (command.Length > 0 && command[0] == '+')
            {
                var chunk = command.Substring(1);
                current += chunk;
                history.Push(chunk);
                while (history.Count > depth)
                {
                    RemoveBottom(history);
                }
            }
            else if (command.Length == 1 && command[0] == '-')
            {
                if (history.Count > 0)
                {
                    var chunk = history.Pop();
                    current = current.Substring(0, current.Length - chunk.Length);
                }
            }
        }
        return current;
    }

    private static void RemoveBottom(Stack<string> stack)
    {
        var temp = new Stack<string>();
        while (stack.Count > 1)
        {
            temp.Push(stack.Pop());
        }
        stack.Pop();
        while (temp.Count > 0)
        {
            stack.Push(temp.Pop());
        }
    }
}

