public static class Solution
{
    public static void Enqueue(Stack<int> inbox, Stack<int> outbox, int value)
    {
        inbox.Push(value);
    }

    public static int Dequeue(Stack<int> inbox, Stack<int> outbox)
    {
        MoveIfNeeded(inbox, outbox);
        if (outbox.Count == 0)
        {
            throw new InvalidOperationException("Queue is empty.");
        }
        return outbox.Pop();
    }

    public static int Peek(Stack<int> inbox, Stack<int> outbox)
    {
        MoveIfNeeded(inbox, outbox);
        if (outbox.Count == 0)
        {
            throw new InvalidOperationException("Queue is empty.");
        }
        return outbox.Peek();
    }

    private static void MoveIfNeeded(Stack<int> inbox, Stack<int> outbox)
    {
        if (outbox.Count == 0)
        {
            while (inbox.Count > 0)
            {
                outbox.Push(inbox.Pop());
            }
        }
    }
}

