public static class Solution
{
    public static string ProcessBrowserNavigation(string initialPage, IReadOnlyList<string> actions)
    {
        var current = initialPage;
        var back = new Stack<string>();
        var forward = new Stack<string>();
        foreach (var action in actions)
        {
            if (action.Length >= 6 && action.Substring(0, 6) == "visit:")
            {
                back.Push(current);
                forward.Clear();
                current = action.Substring(6);
            }
            else if (action == "back")
            {
                if (back.Count > 0)
                {
                    forward.Push(current);
                    current = back.Pop();
                }
            }
            else if (action == "forward")
            {
                if (forward.Count > 0)
                {
                    back.Push(current);
                    current = forward.Pop();
                }
            }
        }
        return current;
    }
}

