public static class Solution
{
    public static int LongestValidParentheses(string s)
    {
        var stack = new Stack<int>();
        stack.Push(-1);
        var max = 0;
        for (var i = 0; i < s.Length; i++)
        {
            if (s[i] == '(')
            {
                stack.Push(i);
            }
            else
            {
                stack.Pop();
                if (stack.Count == 0)
                {
                    stack.Push(i);
                }
                else
                {
                    var length = i - stack.Peek();
                    if (length > max)
                    {
                        max = length;
                    }
                }
            }
        }
        return max;
    }
}

