public record Point(double X, double Y);
public record Polygon(IReadOnlyList<Point> Points);

public static class Solution
{
    public static double Perimeter(Polygon p)
    {
        if (p.Points.Count < 2) return 0;
        double sum = 0;
        for (int i = 0; i < p.Points.Count; i++)
        {
            var a = p.Points[i];
            var b = p.Points[(i + 1) % p.Points.Count];
            double dx = b.X - a.X;
            double dy = b.Y - a.Y;
            sum += Math.Sqrt(dx * dx + dy * dy);
        }
        return sum;
    }

    public static double Area(Polygon p)
    {
        if (p.Points.Count < 3) return 0;
        double sum = 0;
        for (int i = 0; i < p.Points.Count; i++)
        {
            var a = p.Points[i];
            var b = p.Points[(i + 1) % p.Points.Count];
            sum += a.X * b.Y - b.X * a.Y;
        }
        return Math.Abs(sum) / 2.0;
    }
}

