public record Triangle(double A, double B, double C);

public static class Solution
{
    public static double Perimeter(Triangle t) => t.A + t.B + t.C;

    public static bool IsValid(Triangle t)
    {
        return t.A > 0 && t.B > 0 && t.C > 0 &&
               t.A + t.B > t.C && t.A + t.C > t.B && t.B + t.C > t.A;
    }

    public static double Area(Triangle t)
    {
        if (!IsValid(t)) return 0.0;
        double s = Perimeter(t) / 2.0;
        return Math.Sqrt(s * (s - t.A) * (s - t.B) * (s - t.C));
    }
}

