public record RegularPolygon(int Sides, double SideLength);

public static class Solution
{
    public static double Perimeter(RegularPolygon p)
    {
        if (p.Sides < 3) return 0.0;
        return p.Sides * p.SideLength;
    }

    public static double Apothem(RegularPolygon p)
    {
        if (p.Sides < 3) return 0.0;
        return p.SideLength / (2.0 * Math.Tan(Math.PI / p.Sides));
    }

    public static double Area(RegularPolygon p)
    {
        if (p.Sides < 3) return 0.0;
        return 0.5 * Perimeter(p) * Apothem(p);
    }
}

