public record Point(double X, double Y);
public record Polygon(Point[] Points);

public static class Solution
{
    public static double Perimeter(Polygon p)
    {
        Point[] pts = p.Points;
        if (pts.Length < 2)
        {
            return 0;
        }

        double total = 0;
        for (int i = 0; i < pts.Length; i++)
        {
            Point a = pts[i];
            Point b = pts[(i + 1) % pts.Length];
            total += Distance(a, b);
        }
        return total;
    }

    public static double Area(Polygon p)
    {
        Point[] pts = p.Points;
        if (pts.Length < 3)
        {
            return 0;
        }

        double sum = 0;
        for (int i = 0; i < pts.Length; i++)
        {
            Point a = pts[i];
            Point b = pts[(i + 1) % pts.Length];
            sum += a.X * b.Y - b.X * a.Y;
        }
        return Math.Abs(sum) / 2.0;
    }

    private static double Distance(Point a, Point b)
    {
        double dx = a.X - b.X;
        double dy = a.Y - b.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }
}

