public record ShapeCollection(Rectangle[] Rectangles, Circle[] Circles);

public static class Solution
{
    public static double TotalArea(ShapeCollection shapes)
    {
        double total = 0;
        foreach (Rectangle r in shapes.Rectangles)
        {
            total += r.Width * r.Height;
        }
        foreach (Circle c in shapes.Circles)
        {
            total += Math.PI * c.Radius * c.Radius;
        }
        return total;
    }

    public static double TotalPerimeter(ShapeCollection shapes)
    {
        double total = 0;
        foreach (Rectangle r in shapes.Rectangles)
        {
            total += 2 * (r.Width + r.Height);
        }
        foreach (Circle c in shapes.Circles)
        {
            total += 2 * Math.PI * c.Radius;
        }
        return total;
    }
}

