public record Triangle(Point A, Point B, Point C)
{
    private double SideAB => Distance(A, B);
    private double SideBC => Distance(B, C);
    private double SideCA => Distance(C, A);

    public double Perimeter => SideAB + SideBC + SideCA;

    public double Area
    {
        get
        {
            double s = Perimeter / 2;
            return Math.Sqrt(s * (s - SideAB) * (s - SideBC) * (s - SideCA));
        }
    }

    private static double Distance(Point p1, Point p2)
    {
        double dx = p1.X - p2.X;
        double dy = p1.Y - p2.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }
}

