public record Polygon(IReadOnlyList<Point> Points)
{
    public double Area
    {
        get
        {
            double sum = 0;
            for (int i = 0; i < Points.Count; i++)
            {
                Point a = Points[i];
                Point b = Points[(i + 1) % Points.Count];
                sum += a.X * b.Y - b.X * a.Y;
            }
            return Math.Abs(sum) / 2;
        }
