    public double Perimeter
    {
        get
        {
            double total = 0;
            for (int i = 0; i < Points.Count; i++)
            {
                Point a = Points[i];
                Point b = Points[(i + 1) % Points.Count];
                double dx = b.X - a.X;
                double dy = b.Y - a.Y;
                total += Math.Sqrt(dx * dx + dy * dy);
            }
            return total;
        }
    }
}

public static class Solution
{
    public static double Area(Polygon polygon) => polygon.Area;
    public static double Perimeter(Polygon polygon) => polygon.Perimeter;
