public record Point(double X, double Y);
public record Segment(Point Start, Point End);

public static class Solution
{
    public static double Distance(Point a, Point b)
    {
        double dx = a.X - b.X;
        double dy = a.Y - b.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }

    public static double Length(Segment s) => Distance(s.Start, s.End);

    public static double DistanceToPoint(Segment s, Point p)
    {
        double vx = s.End.X - s.Start.X;
        double vy = s.End.Y - s.Start.Y;
        double wx = p.X - s.Start.X;
        double wy = p.Y - s.Start.Y;
        double c1 = vx * wx + vy * wy;
        if (c1 <= 0) return Distance(p, s.Start);
        double c2 = vx * vx + vy * vy;
        if (c2 <= c1) return Distance(p, s.End);
        double t = c1 / c2;
        Point projection = new Point(s.Start.X + t * vx, s.Start.Y + t * vy);
        return Distance(p, projection);
    }
}

