public abstract record Shape;
public record Point(double X, double Y);
public record Circle(Point Center, double Radius) : Shape;
public record Rect(Point TopLeft, double Width, double Height) : Shape;
public record Triangle(Point A, Point B, Point C) : Shape;

public static class Solution
{
    private static double Distance(Point a, Point b)
    {
        double dx = a.X - b.X;
        double dy = a.Y - b.Y;
        return Math.Sqrt(dx * dx + dy * dy);
    }

    public static double Area(Shape shape) => shape switch
    {
        Circle c => Math.PI * c.Radius * c.Radius,
        Rect r => r.Width * r.Height,
        Triangle t => Math.Abs((t.B.X - t.A.X) * (t.C.Y - t.A.Y) - (t.B.Y - t.A.Y) * (t.C.X - t.A.X)) / 2.0,
        _ => throw new ArgumentException("Unknown shape", nameof(shape))
    };

    public static double Perimeter(Shape shape) => shape switch
    {
        Circle c => 2 * Math.PI * c.Radius,
        Rect r => 2 * (r.Width + r.Height),
        Triangle t => Distance(t.A, t.B) + Distance(t.B, t.C) + Distance(t.C, t.A),
        _ => throw new ArgumentException("Unknown shape", nameof(shape))
    };
}

