        return Math.Sqrt(dx * dx + dy * dy);
    }

    public static double Perimeter(Polygon p)
    {
        int n = p.Points.Count;
        if (n < 3) return 0.0;
        double total = 0.0;
        for (int i = 0; i < n; i++)
        {
            total += Distance(p.Points[i], p.Points[(i + 1) % n]);
        }
        return total;
    }

    public static double Area(Polygon p)
    {
        int n = p.Points.Count;
        if (n < 3) return 0.0;
        double sum = 0.0;
        for (int i = 0; i < n; i++)
        {
            Point a = p.Points[i];
            Point b = p.Points[(i + 1) % n];
            sum += a.X * b.Y - b.X * a.Y;
        }
        return Math.Abs(sum) / 2.0;
    }
}

