public static class Solution
{
    public static BankAccount Deposit(BankAccount account, decimal amount)
    {
        if (amount <= 0m) throw new ArgumentException("Amount must be positive.", nameof(amount));
        var txs = account.Transactions.ToList();
        txs.Add(amount);
        return new BankAccount(account.Balance + amount, txs);
    }

    public static BankAccount Withdraw(BankAccount account, decimal amount)
    {
        if (amount <= 0m) throw new ArgumentException("Amount must be positive.", nameof(amount));
        if (amount > account.Balance) throw new InvalidOperationException("Insufficient funds.");
        var txs = account.Transactions.ToList();
        txs.Add(-amount);
        return new BankAccount(account.Balance - amount, txs);
    }
}

