public record BankTransaction(string Kind, decimal Amount);

public static class Solution
{
    public static decimal ApplyTransactions(decimal initialBalance, IEnumerable<BankTransaction> transactions)
    {
        decimal balance = initialBalance;
        foreach (var t in transactions)
        {
            if (t.Amount <= 0m) throw new ArgumentOutOfRangeException(nameof(t.Amount));
            if (t.Kind == "Deposit")
            {
                balance += t.Amount;
            }
            else if (t.Kind == "Withdraw")
            {
                if (t.Amount > balance) throw new InvalidOperationException("Insufficient funds.");
                balance -= t.Amount;
            }
            else
            {
                throw new ArgumentException($"Unknown transaction kind: {t.Kind}", nameof(t.Kind));
            }
        }
        return balance;
    }
}

