public static class Solution
{
    public static BankAccount ProcessTransactions(BankAccount account, IEnumerable<decimal> amounts)
    {
        var balance = account.Balance;
        foreach (var amount in amounts)
        {
            if (amount >= 0)
            {
                balance += amount;
            }
            else
            {
                var withdrawal = -amount;
                if (withdrawal > balance) throw new InvalidOperationException("Insufficient funds");
                balance -= withdrawal;
            }
        }
        return account with { Balance = balance };
    }
}

