public static class Solution
{
    public static int BinarySearch(int[] values, int target)
    {
        int low = 0;
        int high = values.Length - 1;
        while (low <= high)
        {
            int mid = low + (high - low) / 2;
            if (values[mid] == target)
            {
                return mid;
            }
            if (values[mid] < target)
            {
                low = mid + 1;
            }
            else
            {
                high = mid - 1;
            }
        }
        return -1;
    }
}

