public static class Solution
{
    public static int CountOccurrences(int[] values, int target)
    {
        int FirstIndex()
        {
            int low = 0;
            int high = values.Length - 1;
            int result = -1;
            while (low <= high)
            {
                int mid = low + (high - low) / 2;
                if (values[mid] == target)
                {
                    result = mid;
                    high = mid - 1;
                }
                else if (values[mid] < target)
                {
                    low = mid + 1;
                }
                else
                {
                    high = mid - 1;
                }
            }
            return result;
        }

        int LastIndex()
        {
            int low = 0;
            int high = values.Length - 1;
            int result = -1;
            while (low <= high)
            {
                int mid = low + (high - low) / 2;
                if (values[mid] == target)
                {
                    result = mid;
                    low = mid + 1;
                }
                else if (values[mid] < target)
                {
                    low = mid + 1;
                }
                else
                {
                    high = mid - 1;
                }
            }
            return result;
        }

        int first = FirstIndex();
        if (first == -1)
        {
            return 0;
        }
        int last = LastIndex();
        return last - first + 1;
    }
}

