public static class Solution
{
    public static bool IsValidChecksumCode(string? code)
    {
        if (code == null || code.Length != 8) return false;
        if (code[6] != '-') return false;
        for (int i = 0; i < 6; i++)
        {
            if (!char.IsDigit(code[i])) return false;
        }
        if (!char.IsDigit(code[7])) return false;
        int sum = 0;
        for (int i = 0; i < 6; i++)
        {
            sum += code[i] - '0';
        }
        int checksum = sum % 10;
        int provided = code[7] - '0';
        return checksum == provided;
    }
}

