    public static bool IsValidActivationCode(string? code)
    {
        if (code is null || code.Length != 14) return false;
        if (code[4] != '-' || code[9] != '-') return false;
        for (int i = 0; i < code.Length; i++)
        {
            if (i == 4 || i == 9) continue;
            char c = code[i];
            bool ok = (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
            if (!ok) return false;
        }
        return true;
    }
}

