public static class Solution
{
    public static bool IsValidVerificationCode(string? code)
    {
        if (code is null || code.Length != 6)
        {
            return false;
        }

        if (!code.All(char.IsDigit))
        {
            return false;
        }

        int sum = 0;
        for (int i = 0; i < 5; i++)
        {
            sum += code[i] - '0';
        }

        int check = code[5] - '0';
        return sum % 10 == check;
    }
}

