    public static bool IsValidPromoCode(string? code)
    {
        if (code is null) return false;
        if (code.Length < 6 || code.Length > 10) return false;
        if (!char.IsUpper(code[0])) return false;
        bool hasDigit = false;
        foreach (char c in code)
        {
            if (char.IsDigit(c))
            {
                hasDigit = true;
            }
            else if (!char.IsUpper(c))
            {
                return false;
            }
        }
        return hasDigit;
    }
}

