{
    public static int MaxRowSum(int[,] matrix)
    {
        int rows = matrix.GetLength(0);
        if (rows == 0)
        {
            return 0;
        }

        int cols = matrix.GetLength(1);
        int maxSum = int.MinValue;
        for (int r = 0; r < rows; r++)
        {
            int sum = 0;
            for (int c = 0; c < cols; c++)
            {
                sum += matrix[r, c];
            }
            if (sum > maxSum)
            {
                maxSum = sum;
            }
        }
        return maxSum;
    }
}

