public static class Solution
{
    public static (int Row, int Column) FindFirst(int[,] matrix, int value)
    {
        for (int r = 0; r < matrix.GetLength(0); r++)
        {
            for (int c = 0; c < matrix.GetLength(1); c++)
            {
                if (matrix[r, c] == value)
                {
                    return (r, c);
                }
            }
        }
        return (-1, -1);
    }
}

