{
    public static int CountOccurrences(List<List<int>> matrix, int value)
    {
        int count = 0;
        foreach (List<int> row in matrix)
        {
            foreach (int item in row)
            {
                if (item == value)
                {
                    count++;
                }
            }
        }
        return count;
    }
}

